import { execFileSync } from "node:child_process";
import { readFileSync, readdirSync } from "node:fs";

const rehearsal = process.argv.includes("--dry-run");

// Publication order is dependency order: a consumer never reaches the registry before the
// package it imports. @modyra/angular is absent on purpose — its manifest is generated by
// ng-packagr and published from `packages/angular/dist` by publish-angular.mjs.
const packages = [
  { name: "@modyra/core", dir: "packages/core" },
  { name: "@modyra/widgets", dir: "packages/widgets" },
  { name: "@modyra/styles", dir: "packages/styles" },
  { name: "@modyra/zod", dir: "packages/zod" },
  { name: "@modyra/standard-schema", dir: "packages/standard-schema" },
  { name: "@modyra/eslint-plugin", dir: "packages/eslint-plugin" },
  { name: "@modyra/plain", dir: "packages/plain" },
  { name: "@modyra/lit", dir: "packages/lit" },
  { name: "@modyra/react", dir: "packages/react" },
  { name: "@modyra/vue", dir: "packages/vue" },
  { name: "@modyra/solid", dir: "packages/solid" },
  { name: "@modyra/preact", dir: "packages/preact" },
  { name: "@modyra/svelte", dir: "packages/svelte" },
];

assertListCoversEveryPublishablePackage();

// What is already waiting for approval. Staging the same version twice is an error, and a release
// re-run after a partial failure is the normal repair.
const staged = rehearsal ? new Set() : await readStagedVersions();
const publishedAlready = new Set();

for (const pkg of packages) {
  const expectedVersion = readPackageVersion(`${pkg.dir}/package.json`);
  const publishedVersion = await readPublishedVersion(pkg.name);
  if (publishedVersion === expectedVersion) {
    console.log(`Skipping ${pkg.name}@${expectedVersion} (already published)`);
    publishedAlready.add(`${pkg.name}@${expectedVersion}`);
    continue;
  }

  if (!rehearsal && staged.has(`${pkg.name}@${expectedVersion}`)) {
    console.log(`Skipping ${pkg.name}@${expectedVersion} (already staged)`);
    continue;
  }

  // A release stages; it does not publish outright. The tarball and its provenance are uploaded
  // here and a maintainer makes them public with proof of presence, which is what the trusted
  // publisher on each package permits. `--dry-run` is the rehearsal and reaches no registry.
  const publishArgs = rehearsal ? ["publish", "--dry-run"] : ["stage", "publish"];
  if (pkg.name !== "@modyra/styles") {
    publishArgs.push("--access", "public");
  }
  if (shouldUseProvenance()) {
    publishArgs.push("--provenance");
  }
  await publishPackage(pkg.name, pkg.dir, publishArgs, expectedVersion);
}

if (!rehearsal) {
  const nowStaged = await readStagedVersions();
  const missing = packages
    .map((pkg) => `${pkg.name}@${readPackageVersion(`${pkg.dir}/package.json`)}`)
    .filter((spec) => !nowStaged.has(spec) && !publishedAlready.has(spec));
  if (missing.length > 0) {
    throw new Error(`Staged nothing for: ${missing.join(", ")}`);
  }
}

console.log(
  `Workspace packages ${rehearsal ? "rehearsed" : "staged"} coherently`,
);

// A hand-written list silently stops covering the workspace the moment a package is added or
// its `private` flag changes, and the release stays green while a package never ships. The
// list is authoritative for order; the workspace is authoritative for membership.
function assertListCoversEveryPublishablePackage() {
  const publishable = readdirSync("packages", { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => `packages/${entry.name}/package.json`)
    .flatMap((path) => {
      let manifest;
      try {
        manifest = JSON.parse(readFileSync(path, "utf8"));
      } catch {
        return [];
      }
      return manifest.private === true ? [] : [manifest.name];
    })
    // Published from its ng-packagr output, not from its source manifest.
    .filter((name) => name !== "@modyra/angular");

  const listed = new Set(packages.map((pkg) => pkg.name));
  const missing = publishable.filter((name) => !listed.has(name));
  const stale = [...listed].filter((name) => !publishable.includes(name));

  if (missing.length > 0 || stale.length > 0) {
    throw new Error(
      [
        "scripts/publish-workspace.mjs no longer matches the workspace.",
        missing.length > 0 ? `Publishable but unlisted: ${missing.join(", ")}` : "",
        stale.length > 0 ? `Listed but private or absent: ${stale.join(", ")}` : "",
      ]
        .filter(Boolean)
        .join(" "),
    );
  }
}

/** The versions sitting in the staging area, as `name@version`. */
async function readStagedVersions() {
  let output;
  try {
    output = execFileSync("npm", ["stage", "list", "--json"], { encoding: "utf8" });
  } catch (error) {
    // An empty staging area, or a registry that answers nothing useful: neither is a reason to
    // refuse to stage. What matters is the check after staging, which reads it again.
    console.log(`Could not read the staging area: ${String(error.message ?? error).split("\n")[0]}`);
    return new Set();
  }
  try {
    const entries = JSON.parse(output);
    const list = Array.isArray(entries) ? entries : (entries?.staged ?? []);
    return new Set(
      list
        .map((entry) => (entry?.name && entry?.version ? `${entry.name}@${entry.version}` : entry?.spec))
        .filter(Boolean),
    );
  } catch {
    return new Set();
  }
}

function readPackageVersion(packageJsonPath) {
  return JSON.parse(readFileSync(packageJsonPath, "utf8")).version;
}

async function readPublishedVersion(packageName) {
  const response = await fetch(
    `https://registry.npmjs.org/${encodeURIComponent(packageName)}`,
  );
  if (response.status === 404) {
    return null;
  }
  if (!response.ok) {
    throw new Error(`Failed to read ${packageName} from npm: ${response.status}`);
  }
  const metadata = await response.json();
  return metadata["dist-tags"]?.latest ?? null;
}

async function waitForPublishedVersion(packageName, expectedVersion) {
  const maxAttempts = 12;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    const publishedVersion = await readPublishedVersion(packageName);
    if (publishedVersion === expectedVersion) {
      return publishedVersion;
    }
    if (publishedVersion !== null) {
      return publishedVersion;
    }
    if (attempt < maxAttempts) {
      await new Promise((resolve) => setTimeout(resolve, 5000));
    }
  }
  return null;
}

async function publishPackage(packageName, cwd, args, expectedVersion) {
  try {
    execFileSync("npm", args, {
      cwd,
      stdio: "inherit",
    });
  } catch (error) {
    const message = String(error.stderr ?? error.message ?? "");
    if (message.includes("You cannot publish over the previously published versions")) {
      const publishedVersion = await waitForPublishedVersion(packageName, expectedVersion);
      if (publishedVersion === expectedVersion) {
        console.log(`Skipping ${packageName}@${expectedVersion} (already published during retry)`);
        return;
      }
    }
    throw error;
  }
}

function shouldUseProvenance() {
  const value = process.env.NPM_CONFIG_PROVENANCE;
  if (value === undefined) return false;
  return value !== "false" && value !== "0";
}
